# -*- coding: utf-8 -*-
# (speaker, spanish, korean); speaker None => stage direction, "#" => scene heading (neither is a turn)
L, A, G, MA, R = "Lucas", "Amparo", "Alejandra", "Mauricio", "Rodolfo"
D = [
("#", "Escena 1 · 13:22 · En la camioneta de Alejandra, carretera a Santiago", "장면 1 · 오후 1시 22분 · 알레한드라의 차, 산티아고행 국도"),
(None, "Sábado 12 de abril. Alejandra los recoge en el hotel a la una y veinte. Lucas y Amparo llevan esperando en la puerta desde las doce y cincuenta, vestidos de domingo pero sin corbata.", "4월 12일 토요일. 알레한드라가 1시 20분에 호텔로 두 사람을 데리러 온다. 루카스와 암파로는 12시 50분부터 문 앞에서 기다렸다. 나들이 옷차림이지만 넥타이는 없다."),
(G, "¡Súbanse, súbanse! Ya sé, ya sé, es la una y veinte. Había un tráfico horrible en Gómez Morín.", "타세요, 타세요! 알아요, 알아요, 1시 20분이죠. 고메스 모린 대로가 엄청 막혔어요."),
(L, "No pasa nada, señora Garza. ¿Vamos a llegar tarde?", "괜찮아요, 가르사 씨. 우리 늦는 거예요?"),
(G, "Vamos a llegar... a la hora mexicana. El ingeniero ya lo sabe. A mí me perdona. A ustedes, no sé.", "도착은… 멕시코 시간에 맞춰 하겠죠. 엔지니어님도 알아요. 저는 용서해 줘요. 두 분은 모르겠고."),
(A, "Le hemos traído un regalo: aceite de oliva y una botella de vino de Castellón. ¿Está bien?", "선물 가져왔어요. 올리브유랑 카스테욘 와인 한 병. 괜찮을까요?"),
(G, "Perfecto. Nada caro y nada de corbata. ¿Se acuerdan de las reglas?", "완벽해요. 비싼 거 안 되고 넥타이 안 되고. 규칙 기억하세요?"),
(L, "No hablar de negocios. Si él saca el tema, contestar. Si no, comer.", "사업 얘기 금지. 그분이 꺼내면 대답하기. 아니면 먹기."),
(G, "Y tomar. Y platicar. Y otra cosa: a la esposa del ingeniero, Lorena, la saludan primero. En esa casa, quien manda es ella.", "그리고 마시기. 수다 떨기. 하나 더요. 엔지니어님 부인 로레나에게 먼저 인사하세요. 그 집에선 그분이 대장이에요."),
(A, "¿Y de fútbol? Mi hijo me ha hecho una lista: Rayados, sí; Tigres, no.", "축구는요? 아들이 목록을 만들어 줬어요. 라야도스는 좋고, 티그레스는 안 된다고."),
(G, "(ríe) ¡Su hijo es un sabio! El ingeniero es rayado de toda la vida. Si alguien le habla bien de los Tigres, se acabó el negocio.", "(웃으며) 아드님이 현자네요! 엔지니어님은 평생 라야도스 팬이에요. 누가 티그레스 칭찬을 하면 거래는 끝이에요."),
(L, "¿Y Rodolfo? ¿También viene?", "로돌포도 와요?"),
(G, "Rodolfo está allá desde la mañana. Cuando hay carne asada, siempre llega el primero. Es el que más sabe de pisos y el que más come.", "로돌포는 아침부터 거기 있어요. 카르네 아사다가 있으면 항상 제일 먼저 가요. 바닥재를 제일 잘 알고, 제일 많이 먹는 사람이에요."),
(None, "La camioneta deja la ciudad. La carretera sube entre cerros verdes; a la izquierda, la sierra.", "차가 도시를 벗어난다. 초록빛 언덕 사이로 길이 오르막이 되고, 왼쪽으로 산맥이 펼쳐진다."),
(A, "¡Qué bonito! No me imaginaba Monterrey tan verde.", "예쁘다! 몬테레이가 이렇게 푸를 줄 몰랐어요."),
(G, "Esto ya es Santiago. Pueblo Mágico. Aquí tienen sus quintas los que pueden. Los fines de semana, media ciudad se viene para acá.", "여긴 벌써 산티아고예요. '마법의 마을'이죠. 여유 있는 사람들은 여기 별장을 갖고 있어요. 주말이면 도시 사람 반이 이리 와요."),
(L, "¿Una quinta es como una casa de campo?", "'킨타'는 시골 별장 같은 거예요?"),
(G, "Eso. Una casa con terreno, árboles, asador... y, si eres el ingeniero Elizondo, con río.", "그거예요. 땅이랑 나무랑 바비큐 화덕이 있는 집… 그리고 엔지니어 엘리손도라면, 강까지 있죠."),

("#", "Escena 2 · 14:05 · La quinta de los Elizondo, junto al asador", "장면 2 · 오후 2시 5분 · 엘리손도 가족의 별장, 화덕 옆"),
(None, "Una casa de piedra entre nogales. Huele a carbón y a carne. Unas veinte personas: niños corriendo, señoras bajo una palapa, hombres alrededor del asador. Lorena, la esposa del ingeniero, los recibe en la puerta y les señala a su marido. Mauricio Elizondo, unos sesenta años, camisa vaquera y pinzas en la mano, mira el reloj.", "호두나무 사이의 돌집. 숯과 고기 냄새가 난다. 스무 명쯤 모여 있다. 뛰어다니는 아이들, 야자잎 지붕 아래 부인들, 화덕 주위의 남자들. 엔지니어의 부인 로레나가 문 앞에서 맞이하며 남편을 가리킨다. 예순쯤 된 마우리시오 엘리손도가 웨스턴 셔츠 차림에 집게를 들고 시계를 본다."),
(MA, "¡Alejandra! La una y cuarenta... no, las dos y cinco. ¡Bienvenidos a la hora regia!", "알레한드라! 1시 40분… 아니, 2시 5분이네. 몬테레이 시간에 오신 걸 환영합니다!"),
(G, "Ingeniero, el tráfico de Gómez Morín...", "엔지니어님, 고메스 모린 대로가…"),
(MA, "Siempre es el tráfico de Gómez Morín. (a Lucas y Amparo) Mucho gusto. Mauricio Elizondo. Aquí en mi casa, nada de «ingeniero». Mauricio.", "늘 고메스 모린이지. (루카스와 암파로에게) 반갑습니다. 마우리시오 엘리손도입니다. 우리 집에선 '엔지니어'는 빼고요. 그냥 마우리시오."),
(L, "Mucho gusto, Mauricio. Lucas Ferrer. Gracias por recibirnos.", "반갑습니다, 마우리시오. 루카스 페레르입니다. 초대해 주셔서 감사합니다."),
(A, "Amparo Albalat. Encantada. Le hemos traído un pequeño regalo de Onda.", "암파로 알발라트예요. 반갑습니다. 온다에서 작은 선물을 가져왔어요."),
(MA, "(abre la bolsa) Aceite... y vino. ¿De Castellón? No sabía que en Castellón se hacía vino.", "(봉투를 열며) 올리브유… 그리고 와인. 카스테욘산? 카스테욘에서 와인을 만드는 줄은 몰랐네요."),
(A, "Poco, pero bueno. Como nuestra cerámica.", "많진 않지만 좋아요. 우리 타일처럼요."),
(MA, "(ríe) Ya empezó a vender. Me gusta. Pero hoy no se vende nada. Hoy se come. ¿Una cervecita?", "(웃으며) 벌써 영업 시작이네. 마음에 들어요. 그래도 오늘은 아무것도 안 팝니다. 오늘은 먹는 날. 맥주 한잔?"),
(L, "Con mucho gusto.", "기꺼이요."),
(MA, "A ver, ¿qué les sirvo? Tengo arrachera, costilla, chorizo... y, para los valientes, cabrito.", "자, 뭘 드릴까? 아라체라, 갈비, 초리소… 용감한 분들을 위해선 카브리토도 있어요."),
(A, "A mí me gustaría probar el cabrito. En España lo hacemos al horno.", "저는 카브리토를 먹어 보고 싶어요. 스페인에선 오븐에 굽거든요."),
(MA, "Aquí, al pastor: con leña, tres horas. A mí me gusta más la arrachera, pero el cabrito es el orgullo de la casa. ¿Y usted, Lucas?", "여기선 '알 파스토르'로, 장작불에 세 시간 구워요. 저는 아라체라가 더 좋지만, 카브리토가 우리 집 자랑이죠. 루카스는요?"),
(L, "A mí, de todo un poquito.", "저는 다 조금씩이요."),
(MA, "¡Así se habla! «De todo un poquito». Ya habla como de aquí. Pásenle a la mesa, ahorita les llevo.", "그렇지! '다 조금씩'. 벌써 여기 사람처럼 말하네. 식탁으로 가세요, 금방 갖다 드릴게요."),
(None, "Bajo la palapa: tortillas de harina, frijoles charros, guacamole y cinco salsas. Rodolfo Leal se levanta para saludarlos.", "야자잎 지붕 아래 밀가루 토르티야, 프리홀레스 차로스, 과카몰레, 소스 다섯 가지. 로돌포 레알이 일어나 인사한다."),
(R, "¡Licenciados! Por fin en persona. Las pantallas no les hacen justicia.", "선생님들! 드디어 직접 뵙네요. 화면이 두 분을 다 못 담았어요."),
(A, "Rodolfo, qué alegría. Después de tantas videollamadas, ya pareces de la familia.", "로돌포, 반가워요. 화상 통화를 그렇게 했더니 벌써 가족 같아요."),
(R, "Pues aquí ya lo son. Siéntense. ¿Ya probaron los frijoles charros? Son de la abuelita de Lorena.", "여기선 벌써 가족이에요. 앉으세요. 프리홀레스 차로스 드셔 봤어요? 로레나 할머니 레시피예요."),
(L, "(prueba) ¡Qué buenos! Llevan... ¿tocino?", "(맛보며) 맛있네요! 이거… 베이컨 들어갔어요?"),
(R, "Tocino, chorizo, chile... todo lo que no recomienda el doctor.", "베이컨, 초리소, 고추… 의사가 말리는 건 다 들어갔죠."),
(None, "Mauricio llega con una tabla de carne y se sienta a la cabecera.", "마우리시오가 고기 도마를 들고 와 상석에 앉는다."),
(MA, "Bueno, españoles, cuéntenme. ¿Qué les ha parecido Monterrey?", "자, 스페인 손님들, 얘기해 봐요. 몬테레이는 어때요?"),
(L, "Caliente. Y muy rápido. Todo el mundo tiene prisa, pero luego nadie llega a la hora.", "더워요. 그리고 아주 빨라요. 다들 바쁜데 정작 제시간에 오는 사람은 없어요."),
(MA, "(ríe a carcajadas) ¡Eso es Monterrey! Lo describió perfecto. ¿Y usted, Amparo?", "(크게 웃으며) 그게 몬테레이지! 완벽하게 설명했네요. 암파로는요?"),
(A, "Me encanta que la gente sea tan directa. En Valencia damos muchas vueltas antes de decir algo.", "사람들이 이렇게 솔직한 게 정말 좋아요. 발렌시아에선 뭐 하나 말하기 전에 엄청 돌려 말하거든요."),
(MA, "Aquí también damos vueltas. Pero más cortitas. (le sirve más carne) ¿Y usted le va a los Rayados o a los Tigres?", "여기도 돌려 말해요. 좀 짧게 돌 뿐이지. (고기를 더 덜어 주며) 그런데 라야도스 편이에요, 티그레스 편이에요?"),
(A, "A los Rayados, por supuesto. Mi hijo me ha prohibido decir otra cosa.", "당연히 라야도스죠. 아들이 다른 말은 절대 하지 말래요."),
(MA, "¡Su hijo es un hombre inteligente! ¿Cuántos años tiene?", "아드님이 똑똑하네요! 몇 살이에요?"),
(A, "Diez. Se llama Marc. Se sabe el nombre de todos los jugadores.", "열 살이요. 이름은 마르크예요. 선수 이름을 다 외워요."),
(MA, "Tráigalo un día. Lo llevo al estadio. Al de verdad, al de los Rayados.", "언제 한번 데려와요. 경기장에 데려갈게요. 진짜 경기장, 라야도스 경기장으로."),
(L, "Mauricio, hablando de estadios, el hotel también va a tener...", "마우리시오, 경기장 얘기가 나와서 말인데요, 호텔도…"),
(None, "Alejandra le da a Lucas una patada discreta por debajo de la mesa.", "알레한드라가 식탁 밑으로 루카스를 슬쩍 걷어찬다."),
(G, "...¿tan buenas vistas como el estadio? ¡Seguro que sí! (cambia de tema) Ingeniero, cuénteles de su abuelo, el que vino de España.", "…경기장처럼 전망이 좋겠냐고요? 당연하죠! (화제를 바꾸며) 엔지니어님, 스페인에서 오신 할아버님 얘기 좀 해 주세요."),
(MA, "(sonríe; ha visto la patada) Mi abuelo era de Cantabria. Llegó en mil novecientos veinte con una maleta y una carta de recomendación. Empezó cargando ladrillos. Cuando murió, tenía una ladrillera.", "(웃으며, 발길질을 봤다) 우리 할아버지는 칸타브리아 사람이었어요. 1920년에 가방 하나랑 추천서 한 장 들고 왔죠. 벽돌 나르는 일부터 시작했어요. 돌아가실 땐 벽돌 공장을 갖고 계셨고."),
(L, "Una historia parecida a la de la familia de Amparo. Su abuelo empezó con un horno de leña.", "암파로 집안 얘기랑 비슷하네요. 암파로 할아버님은 장작 가마 하나로 시작하셨어요."),
(A, "En mil novecientos cincuenta y ocho. Un solo horno. Y mi padre todavía dice que la mejor cerámica salía de ahí.", "1958년에요. 가마 딱 하나. 아빠는 아직도 제일 좋은 타일은 거기서 나왔다고 해요."),
(MA, "Los viejos siempre dicen eso. Mi papá decía que los mejores ladrillos eran los de mi abuelo. Y se caían a pedazos. (todos ríen)", "어른들은 늘 그래요. 우리 아버지도 할아버지 벽돌이 최고였다고 했죠. 그런데 그게 다 부서졌어요. (모두 웃는다)"),

("#", "Escena 3 · 16:40 · La mesa bajo el nogal", "장면 3 · 오후 4시 40분 · 호두나무 아래 식탁"),
(None, "Han pasado dos horas. Llegan los postres: glorias de Linares y café de olla. Los niños se bañan en el río. Rodolfo saca el celular y le enseña una foto a Amparo.", "두 시간이 흘렀다. 디저트로 리나레스의 '글로리아' 과자와 냄비 커피가 나온다. 아이들은 강에서 물놀이를 한다. 로돌포가 휴대폰을 꺼내 암파로에게 사진을 보여 준다."),
(R, "Amparo, una pregunta de ingeniero, no de negocios. Mire esto. Es un piso que pusimos hace dos años en un centro comercial. ¿Por qué se manchó?", "암파로, 사업 말고 기술자로서 질문 하나요. 이것 좀 보세요. 2년 전에 쇼핑몰에 깐 바닥인데요. 왜 얼룩이 졌을까요?"),
(A, "(amplía la foto) ¿Es un porcelánico pulido?", "(사진을 확대하며) 연마 마감 자기질 타일이에요?"),
(R, "Pulido, sí. Italiano, por cierto.", "연마 마감 맞아요. 참고로 이탈리아산이고요."),
(A, "El pulido abre los microporos de la superficie. Si en fábrica no le aplican un tratamiento antimanchas, absorbe el café, el aceite... todo.", "연마하면 표면의 미세 기공이 열려요. 공장에서 얼룩 방지 처리를 안 하면 커피, 기름… 다 빨아들여요."),
(R, "¿Y los suyos?", "선생님네 건요?"),
(A, "Los nuestros llevan un tratamiento antimanchas después del pulido. Y la absorción de agua de la pieza es inferior al cero coma cinco por ciento. Es lo que exige la norma para el porcelánico.", "저희 건 연마 후에 얼룩 방지 처리를 해요. 그리고 타일 흡수율이 0.5% 미만이에요. 자기질 타일 규격이 요구하는 수준이죠."),
(MA, "(deja el café) Perdone, ¿usted es química?", "(커피를 내려놓으며) 실례지만, 화학을 전공하셨어요?"),
(A, "Química, sí. Licenciada en Química por la Universidad de Valencia. Aunque llevo diez años vendiendo.", "네, 화학이요. 발렌시아 대학교 화학과를 나왔어요. 영업한 지는 10년 됐지만요."),
(MA, "Pues a mí me interesa más la química que la venta. Explíqueme eso de la absorción. Como si yo fuera albañil.", "나는 영업보다 화학이 더 궁금하네요. 그 흡수율이라는 거 설명해 줘요. 내가 미장이라고 생각하고."),
(A, "Imagínese una esponja y un vaso de cristal. La arcilla normal es como una esponja: chupa agua. El porcelánico, cocido a más de mil doscientos grados, es casi como el vaso.", "스펀지랑 유리컵을 떠올려 보세요. 보통 점토는 스펀지 같아서 물을 빨아들여요. 1,200도 넘게 구운 자기질 타일은 거의 유리컵 같고요."),
(MA, "¿Y eso para qué me sirve a mí?", "그게 나한테 무슨 소용이죠?"),
(A, "Para que no se rompa con las heladas, para que no se manche en la cocina y para que dure cuarenta años sin cambiar de color.", "서리에 깨지지 않고, 주방에서 얼룩지지 않고, 40년 동안 색이 변하지 않게요."),
(MA, "Aquí heladas casi no hay, pero el sol pega fuerte. ¿El color aguanta el sol?", "여긴 서리는 거의 없지만 햇볕이 세요. 색이 햇볕을 견뎌요?"),
(A, "El color va en el esmalte, cocido con la pieza. No es pintura. El sol no lo toca.", "색은 유약에 들어 있고 타일과 함께 구워져요. 페인트가 아니에요. 햇볕이 손댈 수 없어요."),
(R, "Es cierto, ingeniero. Yo lo vi en las muestras: la tinta digital queda dentro.", "맞아요, 엔지니어님. 샘플에서 봤어요. 디지털 잉크가 안에 들어가 있어요."),
(MA, "¿Y los resbalones? En las terrazas, cuando llueve, la gente se cae.", "미끄러지는 건요? 테라스에 비가 오면 사람들이 넘어져요."),
(A, "Para exterior se usa un acabado antideslizante. Tiene una textura que no se ve, pero que se nota con el pie mojado.", "실외에는 미끄럼 방지 마감을 써요. 눈에는 안 보이지만 젖은 발로 밟으면 느껴지는 질감이 있어요."),
(MA, "¿Ustedes lo tienen?", "그쪽도 그거 있어요?"),
(A, "Lo tenemos. Se lo enseñamos cuando quiera. Pero hoy no, que hoy no se vende nada.", "있어요. 원하실 때 보여 드릴게요. 하지만 오늘은 안 돼요. 오늘은 아무것도 안 판다면서요."),
(MA, "(suelta una carcajada) ¡Me ganó con mis propias palabras! Alejandra, ¿de dónde sacaste a esta señora?", "(크게 웃으며) 내 말로 나를 이겼네! 알레한드라, 이분 어디서 찾았어?"),
(G, "De Onda, ingeniero. Allá las hacen así.", "온다요, 엔지니어님. 거기선 다 이렇게 키워요."),
(L, "Le aseguro que no hay muchas como ella. Ni en Onda.", "장담하는데 이런 분은 많지 않아요. 온다에도요."),
(A, "(algo incómoda) Lucas exagera. Rodolfo, ¿qué adhesivo usaron en ese centro comercial?", "(조금 불편한 듯) 루카스가 과장하는 거예요. 로돌포, 그 쇼핑몰에선 접착제 뭘 썼어요?"),
(R, "Uno normal, del más barato. La constructora quería ahorrar.", "보통 거요, 제일 싼 거. 건설사가 아끼고 싶어 했거든요."),
(A, "Ahí tiene otro problema. Para gran formato hace falta un adhesivo flexible y doble encolado: en la pieza y en el suelo. Si no, la pieza suena hueca y acaba despegándose.", "그게 또 다른 문제예요. 대형 타일엔 유연성 접착제랑 양면 도포가 필요해요. 타일에도, 바닥에도요. 안 그러면 두드렸을 때 속 빈 소리가 나고 결국 떨어져요."),
(R, "¡Eso! Sonaba hueco. Pensé que era culpa de los colocadores.", "그거예요! 속 빈 소리가 났어요. 시공 기술자들 잘못인 줄 알았는데."),
(A, "A veces es de ellos. Pero normalmente es de quien compró el adhesivo.", "그럴 때도 있죠. 하지만 보통은 접착제를 산 사람 잘못이에요."),
(MA, "(mira a Rodolfo) O sea, mía.", "(로돌포를 보며) 그러니까, 내 잘못이네."),
(R, "(tose) Ingeniero, yo no he dicho nada.", "(헛기침하며) 엔지니어님, 저는 아무 말도 안 했어요."),
(MA, "No, lo ha dicho ella. Y tiene razón. (pausa) Alejandra, la próxima vez que me traigas proveedores, que sean así. Que me enseñen algo.", "아니, 이분이 말했지. 그리고 맞는 말이야. (잠시 침묵) 알레한드라, 다음에 공급업체 데려올 땐 이런 사람들로 데려와. 나한테 뭘 가르쳐 줄 수 있는 사람들로."),

("#", "Escena 4 · 19:20 · El mirador sobre el río", "장면 4 · 저녁 7시 20분 · 강이 내려다보이는 전망대"),
(None, "Cae la tarde. Casi todos los invitados se han ido. Mauricio camina con Lucas y Amparo hasta un mirador de piedra sobre el río, con una banca de madera. Al fondo, la sierra se vuelve morada. Alejandra los sigue a unos pasos.", "해가 저문다. 손님들은 거의 다 돌아갔다. 마우리시오가 루카스와 암파로를 데리고 강 위의 돌 전망대까지 걷는다. 나무 벤치가 하나 있다. 저 멀리 산맥이 보랏빛으로 물든다. 알레한드라는 몇 걸음 뒤에서 따라온다."),
(MA, "Cuando era niño, mi papá me traía aquí todos los domingos. Cuando compré la quinta, lo primero que hice fue poner esta banca.", "어릴 때 아버지가 일요일마다 날 여기 데려왔어요. 이 별장을 사고 제일 먼저 한 게 이 벤치를 놓는 거였죠."),
(L, "Es un lugar precioso.", "정말 아름다운 곳이네요."),
(MA, "Es el lugar donde pienso. Y donde hablo de negocios, cuando hay que hablar. (pausa) Bueno. Ya comieron, ya tomaron, ya platicaron. Ahora sí.", "내가 생각하는 곳이에요. 그리고 얘기할 때가 되면 사업 얘기를 하는 곳이고. (잠시 침묵) 자. 먹었고, 마셨고, 수다도 떨었으니. 이제 얘기합시다."),
(L, "Lo escuchamos.", "말씀하세요."),
(MA, "El hotel lo tengo casi decidido. Los italianos firmaron la carta con Alejandra y yo ya les di mi palabra. Y mi palabra vale más que una carta.", "호텔은 거의 정했어요. 이탈리아 사람들이 알레한드라와 의향서에 서명했고, 나도 약속을 했어요. 그리고 내 약속은 종이 한 장보다 무거워요."),
(A, "Lo entendemos.", "이해합니다."),
(MA, "Pero hay una cosa que no me gusta. Diez semanas. El hotel abre en diciembre y ya voy atrasado. Si los italianos se retrasan, me quedo sin hotel en Navidad.", "그런데 마음에 안 드는 게 하나 있어요. 10주. 호텔은 12월에 개장하는데 벌써 늦어지고 있어요. 이탈리아 쪽이 늦으면 크리스마스에 호텔이 없는 거죠."),
(L, "Nosotros ofrecemos seis semanas desde el anticipo.", "저희는 선수금 입금 후 6주를 제안합니다."),
(MA, "Ya lo sé. Alejandra me lo dijo. También me enseñó una foto en su celular. Una montaña dentro de un mármol.", "알아요. 알레한드라가 말해 줬어요. 휴대폰으로 사진도 보여 주더군요. 대리석 안에 산이 있는 거."),
(G, "(desde atrás) Se la enseñé como quien no quiere la cosa, ingeniero.", "(뒤에서) 그냥 지나가는 김에 보여 드린 거예요, 엔지니어님."),
(MA, "Tú nunca enseñas nada como quien no quiere la cosa, Alejandra. (a Amparo) ¿Quién tuvo esa idea?", "알레한드라, 당신은 뭘 지나가는 김에 보여 주는 법이 없잖아. (암파로에게) 그 아이디어는 누가 냈어요?"),
(A, "Nuria, nuestra diseñadora. Quería que el vestíbulo del hotel tuviera algo de la ciudad.", "우리 디자이너 누리아요. 호텔 로비에 이 도시의 무언가가 담기길 바랐어요."),
(MA, "El vestíbulo es lo primero que ve quien entra. (piensa) Eso lo voy a pensar.", "로비는 들어오는 사람이 제일 먼저 보는 곳이죠. (생각하며) 그건 생각해 볼게요."),
(L, "¿Y las torres?", "그럼 아파트는요?"),
(MA, "(lo mira) Las torres están abiertas. Doscientos departamentos, cuarenta mil metros de piso. Ahí no le he dado mi palabra a nadie.", "(그를 바라보며) 아파트는 열려 있어요. 2백 세대, 바닥 면적 4만㎡. 거기는 아무한테도 약속 안 했어요."),
(L, "Nos gustaría mucho tener la oportunidad.", "기회를 주시면 정말 좋겠습니다."),
(MA, "La oportunidad ya la tienen. Lo que no tienen es el contrato. Y yo no hago contratos en una banca.", "기회는 벌써 있어요. 없는 건 계약이죠. 그리고 나는 벤치에서 계약하지 않아요."),
(A, "¿Y dónde los hace?", "그럼 어디서 하세요?"),
(MA, "En la oficina de Treviño. Ese hombre lee cada coma como si fuera una bomba.", "트레비뇨 사무실에서. 그 사람은 쉼표 하나하나를 폭탄처럼 읽어요."),
(G, "Es mi abogado, ingeniero. Y también el suyo.", "제 변호사예요, 엔지니어님. 엔지니어님 변호사이기도 하고요."),
(MA, "Por eso. (a Lucas) Vean a Treviño el lunes. Que les explique cómo quiere el contrato: exclusividad, garantías, todo eso. Si el marco me convence, hablamos de números.", "그러니까. (루카스에게) 월요일에 트레비뇨를 만나요. 계약을 어떻게 원하는지 설명해 줄 거예요. 독점, 보증, 그런 것들. 틀이 마음에 들면 숫자 얘기를 합시다."),
(L, "El lunes estaremos allí.", "월요일에 가겠습니다."),
(MA, "Y otra cosa, Lucas. Usted quiso hablar del hotel a media comida. Alejandra le dio una patada. La vi.", "그리고 하나 더, 루카스. 식사 중에 호텔 얘기를 꺼내려 했죠. 알레한드라가 걷어찼고요. 다 봤어요."),
(L, "(avergonzado) Lo siento. Costumbres de Madrid.", "(민망해하며) 죄송합니다. 마드리드 습관이에요."),
(MA, "No lo sienta. Me gusta que la gente tenga prisa. Pero aquí la prisa se esconde. Como la montaña en el mármol.", "미안해할 거 없어요. 사람이 서두르는 거 좋아해요. 다만 여기선 서두르는 걸 숨겨요. 대리석 속의 산처럼."),
(L, "Lo aprenderé.", "배우겠습니다."),
(MA, "(a Amparo) Y usted, Amparo, venga el martes a la obra. Quiero que mis colocadores la oigan hablar del adhesivo.", "(암파로에게) 그리고 암파로, 화요일에 현장에 와요. 우리 시공 기술자들이 접착제 얘기를 들었으면 해요."),
(A, "Con mucho gusto. Llevaré las muestras antideslizantes.", "기꺼이요. 미끄럼 방지 샘플을 가져갈게요."),
(MA, "(ríe) Ya está vendiendo otra vez. (les da la mano) Gracias por venir. Me gusta que hayan aguantado toda la tarde sin hablar de precios. Casi.", "(웃으며) 또 영업이네. (악수하며) 와 줘서 고마워요. 오후 내내 가격 얘기 안 하고 버틴 게 마음에 들어요. 거의요."),
(G, "Ingeniero, gracias por todo. Le marco el lunes.", "엔지니어님, 정말 감사합니다. 월요일에 전화드릴게요."),
(MA, "Márcame cuando quieras, Alejandra. Pero que sea ahorita, no «ahorita».", "언제든 전화해, 알레한드라. 근데 진짜 지금 말이야, '아오리타' 말고."),
(None, "En la camioneta, de vuelta. Ya es de noche; abajo brillan las luces de Monterrey.", "돌아오는 차 안. 벌써 밤이다. 아래로 몬테레이의 불빛이 반짝인다."),
(G, "¿Saben lo que acaba de pasar?", "방금 무슨 일이 있었는지 알아요?"),
(L, "¿Que nos ha mandado a ver al abogado?", "변호사를 만나 보라고 한 거요?"),
(G, "Que el ingeniero Elizondo los llevó a su banca. A su banca no lleva a nadie. Yo tardé cinco años.", "엘리손도 엔지니어님이 두 분을 그 벤치에 데려갔다는 거예요. 거긴 아무도 안 데려가요. 저는 5년 걸렸어요."),
(A, "¿Cinco años?", "5년이요?"),
(G, "Cinco. Y ustedes, una tarde. (mira a Amparo por el retrovisor) Gracias a una esponja y un vaso de cristal.", "5년. 그런데 두 분은 오후 한나절. (백미러로 암파로를 보며) 스펀지랑 유리컵 덕분이죠."),
(A, "Y a una patada por debajo de la mesa.", "그리고 식탁 밑의 발길질 덕분이고요."),
(G, "(ríe) Esa fue gratis, licenciado.", "(웃으며) 그건 공짜였어요, 선생님."),
(L, "Se la agradezco de verdad. (pausa) Entonces, ¿el lunes, Treviño?", "진심으로 감사해요. (잠시 침묵) 그럼, 월요일엔 트레비뇨?"),
(G, "El lunes, Treviño. Y prepárense: él no come carne asada. Él come comas.", "월요일엔 트레비뇨. 그리고 각오하세요. 그 사람은 고기를 안 먹어요. 쉼표를 먹어요."),
(A, "Pues le llevaremos el contrato bien peinado.", "그럼 계약서를 잘 빗질해서 가져가야겠네요."),
]

PRE = [
("text", "장면 미리보기", "대화문을 읽기 전에 줄거리를 확인하고, 아래 질문의 답을 찾으며 읽어 보세요.", [
 "'1시는 1시'라던 토요일. 알레한드라는 1시 20분에 나타나고, 두 사람은 2시 5분에 산티아고의 별장에 도착한다. 숯불 위의 카브리토, 라야도스와 티그레스, 칸타브리아에서 온 할아버지 이야기. 루카스가 호텔 얘기를 꺼내려는 순간 식탁 밑에서 발길질이 날아온다. 디저트가 나올 무렵 암파로는 '스펀지와 유리컵'으로 자기질 타일을 설명해 엔지니어의 마음을 사로잡는다. 해 질 녘, 엘리손도는 두 사람을 아무도 데려가지 않는 강가의 벤치로 데려간다.",
 "듣기 질문 ① 알레한드라가 차 안에서 다시 확인해 준 '규칙'은 무엇인가?",
 "듣기 질문 ② 엘리손도가 이탈리아 업체에 대해 마음에 들지 않는 점은 무엇인가?",
 "듣기 질문 ③ 엘리손도는 월요일에 두 사람에게 무엇을 하라고 하고, 화요일에는 누구를 어디로 부르는가?",
]),
]

